var $=function(id){return (typeof container!=="undefined"&&container?container.querySelector("#"+id):null)||document.getElementById(id);};
function calc(){
  var a=+$("ia").value||1,b=+$("ib").value||1,c=+$("ic").value||1,d=+$("id").value||1;
  var Ie=a/(a+b),Ine=c/(c+d),RR=Ie/Ine,OR=(a*d)/(b*c),RA=Ie-Ine,RAP=RA/Ie;
  var seRR=Math.sqrt(b/(a*(a+b))+d/(c*(c+d)));
  var seOR=Math.sqrt(1/a+1/b+1/c+1/d);
  var rrLo=Math.exp(Math.log(RR)-1.96*seRR),rrHi=Math.exp(Math.log(RR)+1.96*seRR);
  var orLo=Math.exp(Math.log(OR)-1.96*seOR),orHi=Math.exp(Math.log(OR)+1.96*seOR);
  $("rr").textContent=RR.toFixed(2);$("or").textContent=OR.toFixed(2);
  $("ra").textContent=(RA*100).toFixed(1)+"%";$("rap").textContent=(RAP*100).toFixed(1)+"%";
  $("ie").textContent=(Ie*100).toFixed(1)+"%";$("ine").textContent=(Ine*100).toFixed(1)+"%";
  $("rr_ic").textContent="["+rrLo.toFixed(2)+";"+rrHi.toFixed(2)+"]";
  $("or_ic").textContent="["+orLo.toFixed(2)+";"+orHi.toFixed(2)+"]";
  var v=$("bv");
  if(RR>1&&rrLo>1){v.className="badge ok";v.textContent="✓ Association significative";}
  else if(RR<1&&rrHi<1){v.className="badge ok";v.textContent="✓ Facteur protecteur";}
  else{v.className="badge w";v.textContent="⚠ IC contient 1 — non significatif";}
}
["ia","ib","ic","id"].forEach(function(id){$(""+id).addEventListener("input",calc);});
calc();

var $=function(id){return (typeof container!=="undefined"&&container?container.querySelector("#"+id):null)||document.getElementById(id);};
function calc(){
  var a=+$("sA").value,N=+$("sN").value,D=+$("sD").value,P=+$("sP").value,mort=+$("sM").value;
  $("vA").textContent=a;$("vN").textContent=N.toLocaleString("fr");
  $("vD").textContent=D+" ans";$("vP").textContent=P;$("vM").textContent=mort;
  var IC=a/(N*D)*1000,DI=a/(N*D),prev=P/N*1000,cfr=a>0?mort/a*100:0;
  var pA=IC/1000*D*1000,nnt=IC>0?Math.round(1000/IC):Infinity;
  $("ic").textContent=IC.toFixed(2);$("di").textContent=DI.toFixed(4);
  $("prev").textContent=prev.toFixed(1);$("cfr").textContent=cfr.toFixed(1)+"%";
  $("pa").textContent=pA.toFixed(1)+"/1000";$("nnt").textContent=isFinite(nnt)?nnt:"∞";
  var cv=$("cv"),W=(cv&&cv.offsetWidth)||260,H=90;cv.width=W;cv.height=H;
  var ctx=cv.getContext("2d");ctx.fillStyle="#0b0e18";ctx.fillRect(0,0,W,H);
  var bars=[{l:"IC",v:Math.min(IC,100),col:"#00d4c4"},{l:"Prévalence",v:Math.min(prev,100),col:"#f5b93a"},{l:"CFR%",v:Math.min(cfr,100),col:"#f06370"}];
  var bw=(W-24)/3-6;
  bars.forEach(function(b,i){
    var x=12+i*(bw+6),bH=(b.v/100)*(H-22),y=H-12-bH;
    ctx.fillStyle=b.col+"22";ctx.fillRect(x,H-12-(H-22),bw,H-22);
    ctx.fillStyle=b.col;ctx.fillRect(x,y,bw,bH);
    ctx.font="8px system-ui";ctx.textAlign="center";ctx.fillStyle="rgba(221,226,245,.5)";
    ctx.fillText(b.l,x+bw/2,H-2);ctx.fillStyle=b.col;
    ctx.fillText(b.v.toFixed(1),x+bw/2,y-3);
  });
}
["sA","sN","sD","sP","sM"].forEach(function(id){$(""+id).addEventListener("input",calc);});
calc();

var $=function(id){return (typeof container!=="undefined"&&container?container.querySelector("#"+id):null)||document.getElementById(id);};
function calc(){
  var It=$("sIt").value/1000,Ic=$("sIc").value/1000,n=+$("sNs").value;
  $("vIt").textContent=(It*100).toFixed(1)+"%";$("vIc").textContent=(Ic*100).toFixed(1)+"%";$("vNs").textContent=n;
  var RR=It/Ic,OR=(It/(1-It))/(Ic/(1-Ic)),RRA=Ic-It,RRR=RRA/Ic,NNT=Math.round(1/RRA);
  var se=Math.sqrt((1-It)/(n*It)+(1-Ic)/(n*Ic));
  var lo=Math.exp(Math.log(RR)-1.96*se),hi=Math.exp(Math.log(RR)+1.96*se);
  $("rr").textContent=RR.toFixed(2);$("or").textContent=OR.toFixed(2);
  $("rra").textContent=(RRA*100).toFixed(1)+"%";$("rrr").textContent=(RRR*100).toFixed(1)+"%";
  $("nnt").textContent=NNT;
  var cv=$("fp"),W=(cv&&cv.offsetWidth)||260,H=70;cv.width=W;cv.height=H;
  var ctx=cv.getContext("2d");ctx.fillStyle="#0b0e18";ctx.fillRect(0,0,W,H);
  var mx=W/2,cy=H/2;
  var xOf=function(v){return Math.max(8,Math.min(W-8,mx+Math.log(v)/2*(W-40)/2));};
  ctx.strokeStyle="rgba(255,255,255,.25)";ctx.lineWidth=1.5;ctx.setLineDash([4,4]);
  ctx.beginPath();ctx.moveTo(mx,8);ctx.lineTo(mx,H-18);ctx.stroke();ctx.setLineDash([]);
  var x0=xOf(lo),x1=xOf(hi),xm=xOf(RR);
  ctx.strokeStyle="#00d4c4";ctx.lineWidth=2.5;
  ctx.beginPath();ctx.moveTo(x0,cy);ctx.lineTo(x1,cy);ctx.stroke();
  ctx.strokeStyle="#00d4c4";ctx.lineWidth=2;
  ctx.beginPath();ctx.moveTo(x0,cy-5);ctx.lineTo(x0,cy+5);ctx.stroke();
  ctx.beginPath();ctx.moveTo(x1,cy-5);ctx.lineTo(x1,cy+5);ctx.stroke();
  ctx.fillStyle="#00d4c4";ctx.beginPath();ctx.moveTo(xm,cy-8);ctx.lineTo(xm+8,cy);ctx.lineTo(xm,cy+8);ctx.lineTo(xm-8,cy);ctx.closePath();ctx.fill();
  ctx.fillStyle="rgba(221,226,245,.6)";ctx.font="8px monospace";ctx.textAlign="center";
  ctx.fillText("RR="+RR.toFixed(2)+" ["+lo.toFixed(2)+";"+hi.toFixed(2)+"]",mx,12);
  [0.5,1,2].forEach(function(v){
    var x=xOf(v);ctx.fillStyle="rgba(221,226,245,.25)";ctx.font="7px monospace";ctx.textAlign="center";ctx.fillText(v,x,H-4);
  });
}
["sIt","sIc","sNs"].forEach(function(id){$(""+id).addEventListener("input",calc);});
calc();

