function draw(){
  var cv=$("cv"),W=(cv&&cv.offsetWidth)||260,H=160;cv.width=W;cv.height=H;
  var ctx=cv.getContext("2d");ctx.fillStyle="#0b0e18";ctx.fillRect(0,0,W,H);
