    var f=(i+1)/STUDIES.length,bw=f*(W-20),x=(W-bw)/2;
    var bh=(H-10)/STUDIES.length-3,y=i*(bh+3)+5;
    ctx.fillStyle=s.col;ctx.globalAlpha=0.25+i*0.07;
    ctx.beginPath();ctx.roundRect(x,y,bw,bh,3);ctx.fill();ctx.globalAlpha=1;
    ctx.strokeStyle=s.col;ctx.lineWidth=1;ctx.globalAlpha=0.6;
    ctx.beginPath();ctx.roundRect(x,y,bw,bh,3);ctx.stroke();ctx.globalAlpha=1;
    ctx.fillStyle=s.col;ctx.font="bold 8px system-ui";ctx.textAlign="center";
    ctx.fillText(s.n+" (Nv."+s.lvl+")",W/2,y+bh/2+3);
  });
