function drawTL(sel){
  var cv=$("cv"),W=(cv&&cv.offsetWidth)||260,H=90;cv.width=W;cv.height=H;
  var ctx=cv.getContext("2d");ctx.fillStyle="#0b0e18";ctx.fillRect(0,0,W,H);
  var pad=28,tw=W-pad*2;
  ctx.strokeStyle="rgba(221,226,245,.2)";ctx.lineWidth=1.5;
  ctx.beginPath();ctx.moveTo(pad,H/2);ctx.lineTo(W-pad,H/2);ctx.stroke();
  [1984,2000,2010,2019,2024].forEach(function(y){
    var x=pad+(y-1980)/(2025-1980)*tw;
    ctx.fillStyle="rgba(221,226,245,.2)";ctx.fillRect(x,H/2-3,1,6);
    ctx.fillStyle="rgba(221,226,245,.25)";ctx.font="6px monospace";ctx.textAlign="center";ctx.fillText(y,x,H/2+14);
  });
  [{n:"PMSI",s:1984,e:2024,y:H/2-18,col:"#00d4c4"},{n:"Sentinelles",s:1984,e:2024,y:H/2-28,col:"#a07de0"},
   {n:"SNDS",s:2006,e:2024,y:H/2+4,col:"#f5b93a"},{n:"EPI-PHARE",s:2019,e:2024,y:H/2+14,col:"#74b08a"},
   {n:"CépiDc",s:1970,e:2024,y:H/2-38,col:"#f06370"}].forEach(function(t,i){
