var $=function(id){return (typeof container!=="undefined"&&container?container.querySelector("#"+id):null)||document.getElementById(id);};
var QN=[
  {q:"EI déjà décrit pour ce médicament ?",yes:1,no:-1},
  {q:"EI apparu après la prise ?",yes:2,no:-1},
  {q:"EI amélioré à l'arrêt du médicament ?",yes:1,no:0},
  {q:"EI réapparu à la reprise ?",yes:2,no:-1},
  {q:"Autre cause possible ?",yes:-1,no:2},
  {q:"EI ré-apparu avec placebo ?",yes:-1,no:1},
  {q:"Concentration toxique documentée ?",yes:1,no:0},
  {q:"EI dose-dépendant ?",yes:1,no:0},
  {q:"Patient déjà exposé ?",yes:1,no:0},
  {q:"EI confirmé objectivement ?",yes:1,no:0},
];
var nar=$("naranjo");
QN.forEach(function(q,i){
  var row=document.createElement("div");
  row.style.cssText="display:flex;align-items:center;gap:5px;font-size:9px;color:var(--t2)";
  row.innerHTML="<span style=\"flex:1;line-height:1.3\">"+q.q+"</span>"
    +"<select id=\"nq"+i+"\" style=\"background:rgba(255,255,255,.06);border:1px solid var(--bd);color:var(--t);border-radius:5px;padding:2px 4px;font-size:8px;cursor:pointer\">"
    +"<option value=\"na\">NA</option><option value=\"yes\">Oui(+"+q.yes+")</option>"
    +"<option value=\"no\">Non("+q.no+")</option></select>";
  if(nar)nar.appendChild(row);
  document.getElementById("nq"+i).addEventListener("change",calcN);
});
function calcN(){
  var s=0;QN.forEach(function(q,i){var el=document.getElementById("nq"+i);if(!el)return;var v=el.value;if(v==="yes")s+=q.yes;else if(v==="no")s+=q.no;});
  $("nScore").textContent=s;
  var lv=s>=9?"Certain":s>=5?"Probable":s>=1?"Possible":"Douteux";
  var col=s>=9?"var(--r)":s>=5?"var(--a)":s>=1?"var(--c)":"var(--t3)";
  $("nLevel").textContent=lv;$("nLevel").style.color=col;
}
function calcP(){
  var n1=+$("sN1").value,n2=+$("sN2").value,n3=+$("sN3").value,n4=+$("sN4").value;
  $("vN1").textContent=n1;$("vN2").textContent=n2;$("vN3").textContent=n3;$("vN4").textContent=(n4/1000).toFixed(0)+"k";
  var a=n1,b=n2-n1,c=n3,dv=n4-n3;
  var PRR=(a/(a+b))/(c/(c+dv));
  var N=a+b+c+dv,E=((a+b)*(a+c))/N,chi2=Math.pow(a-E,2)/E;
  $("prr").textContent=PRR.toFixed(2);
  var sig=PRR>=2&&chi2>=4&&n1>=3;
  $("signal").textContent=sig?"✓ SIGNAL":"✗ Pas de signal";
  $("signal").style.color=sig?"var(--r)":"var(--t3)";
}
["sN1","sN2","sN3","sN4"].forEach(function(id){var el=$(id);if(el)el.addEventListener("input",calcP);});
calcP();calcN();

var $=function(id){return (typeof container!=="undefined"&&container?container.querySelector("#"+id):null)||document.getElementById(id);};
function calcSMR(){
  var obs=+$("sObs").value,exp=+$("sExp").value;
  $("vObs").textContent=obs;$("vExp").textContent=exp;
  var smr=obs/exp*100;$("smr").textContent=smr.toFixed(1);
  var msg=smr>110?"Surmortalité":smr<90?"Sous-mortalité":"≈ Référence";
  var col=smr>110?"var(--r)":smr<90?"var(--g)":"var(--c)";
  $("smrI").textContent=msg;$("smrI").style.color=col;
}
function calcD(){
  var se=$("sSe").value/100,sp=$("sSp").value/100,prev=$("sPrev").value/100;
  $("vSe").textContent=Math.round(se*100)+"%";$("vSp").textContent=Math.round(sp*100)+"%";$("vPrev").textContent=Math.round(prev*100)+"%";
  var vpp=se*prev/(se*prev+(1-sp)*(1-prev));
  var vpn=sp*(1-prev)/(sp*(1-prev)+(1-se)*prev);
  $("vpp").textContent=(vpp*100).toFixed(1)+"%";$("vpn").textContent=(vpn*100).toFixed(1)+"%";
  $("rvp").textContent=(se/(1-sp)).toFixed(1);$("rvm").textContent=((1-se)/sp).toFixed(2);
}
function calcICER(){
  var dc=+$("sDC").value,dq=$("sDQ").value/100;
  $("vDC").textContent=dc.toLocaleString("fr")+" €";$("vDQ").textContent=dq.toFixed(2);
  var icer=dq>0?dc/dq:Infinity;
  $("icer").textContent=icer<1e6?Math.round(icer).toLocaleString("fr")+" €":"∞";
  var ok=icer<=50000;
  $("icerV").textContent=ok?"✓ Efficient":"✗ Non efficient";
  $("icerV").style.color=ok?"var(--g)":"var(--r)";
}
$("sObs").addEventListener("input",calcSMR);$("sExp").addEventListener("input",calcSMR);
["sSe","sSp","sPrev"].forEach(function(id){$(""+id).addEventListener("input",calcD);});
$("sDC").addEventListener("input",calcICER);$("sDQ").addEventListener("input",calcICER);
calcSMR();calcD();calcICER();
